const MONTH_NAMES = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
// One distinct color per calendar month (Jan..Dec), independent of year — used
// to color-code "last 3 losses" chips so e.g. every August loss shares a color.
