// Day-header line like "01/08/2023 00:00" marks the start of a new day's
// block of space-separated tokens (e.g. "R0 R1 G2 D3 ..." — letter = signal,
// number = minute-of-day index, 0 = 00:00).
const DAY_HEADER_RE = /^(\d{2})\/(\d{2})\/(\d{4})\s+\d{2}:\d{2}$/;

function parseSequenceTxt(text) {
  const targetTimes = [...new Set(DEFAULT_SLOTS.flatMap(s => s.times))]
    .sort((a,b) => a.localeCompare(b));

  const days = new Map();
  let resolved = null;

  const lines = text.split(/\r?\n/);
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;

    const header = line.match(DAY_HEADER_RE);
    if (header) {
      const [, dd, mm, yyyy] = header;
      const dateKey = `${yyyy}.${mm}.${dd}`;
      resolved = {};
      days.set(dateKey, resolved);
      continue;
    }
    if (!resolved) continue;

    const candles = [];
    for (const tok of line.split(/\s+/)) {
      const sig = tok[0];
      const idx = parseInt(tok.slice(1), 10);
      if ((sig !== "G" && sig !== "R" && sig !== "D") || !Number.isFinite(idx)) continue;
      const hh = String(Math.floor(idx / 60)).padStart(2, "0");
      const mm2 = String(idx % 60).padStart(2, "0");
      candles.push({ time:`${hh}:${mm2}`, sig });
    }
    candles.sort((a,b) => a.time.localeCompare(b.time));

    // Exact screenshot rule: if the candle at a selected slot is Doji,
    // keep the slot time fixed and use the NEXT NON-DOJI candle's G/R.
    for (const target of targetTimes) {
      const c = candles.find(x => x.time >= target && x.sig !== "D");
      if (c) resolved[target] = c.sig;
    }
  }

  const allDates = [...days.keys()].sort();
  return { days, minDate: allDates[0] || null, maxDate: allDates[allDates.length - 1] || null };
}

// Always store dates as YYYY.MM.DD so uploaded rows line up with the existing
// data (2026.08.25, 2026-08-25 and 25/08/2026 all become 2026.08.25).
function normDate(str) {
  const t = String(str).trim();
  let m = t.match(/^(\d{4})[.\-\/](\d{2})[.\-\/](\d{2})/);
  if (m) return `${m[1]}.${m[2]}.${m[3]}`;
  m = t.match(/^(\d{2})[.\-\/](\d{2})[.\-\/](\d{4})/);
  if (m) return `${m[3]}.${m[2]}.${m[1]}`;
  return t;
}

const toMinutes = hhmm => { const [h,m] = hhmm.split(":").map(Number); return h*60 + m; };

function parseCsv(text) {
  // Auto-detect: per-day minute-index sequence format vs tab-separated OHLC CSV.
  const firstLine = text.split(/\r?\n/).find(l => l.trim());
  if (firstLine && DAY_HEADER_RE.test(firstLine.trim())) {
    return parseSequenceTxt(text);
  }

  const lines = text.split(/\r?\n/).filter(Boolean);
  if (!lines.length) return { days:new Map(), minDate:null, maxDate:null };

  // Delimiter auto-detect: tab (MT5 export), semicolon or comma.
  const delim = lines[0].includes("\t") ? "\t" : lines[0].includes(";") ? ";" : ",";
  const header = lines[0].split(delim).map(x => x.trim().toUpperCase());
  const find = (name, fallback) => {
    const i = header.findIndex(x => x === name || x.includes(name));
    return i >= 0 ? i : fallback;
  };
  const di = find("DATE", 0), ti = find("TIME", 1);
  const oi = find("OPEN", 2), ci = find("CLOSE", 5);

  const candles = [];
  for (let n = 1; n < lines.length; n++) {
    const parts = lines[n].split(delim);
    if (parts.length <= Math.max(di,ti,oi,ci)) continue;

    const date = normDate(parts[di]);
    const time = parts[ti].trim().slice(0,5);
    const open = Number(parts[oi]);
    const close = Number(parts[ci]);
    if (!date || !time || !Number.isFinite(open) || !Number.isFinite(close)) continue;
    candles.push({ date, time, open, close });
  }
  return daysFromCandles(candles);
}

// Core used by BOTH the CSV upload and the API sync.
// candles = [{ date:"YYYY.MM.DD", time:"HH:MM", open, close }] in time order
// -> { days: Map(date -> { "06:45":"G"|"R", ... }), minDate, maxDate }
// Screenshot rule: Doji at a selected slot is skipped and the next non-Doji
// candle supplies that slot's G/R. The selected slot time itself never moves.
function daysFromCandles(candles) {
  const targetTimes = [...new Set(DEFAULT_SLOTS.flatMap(s => s.times))]
    .sort((a,b) => a.localeCompare(b));

  // Group raw candles by broker date first. Each selected slot is resolved
  // independently: exact slot candle if non-Doji; otherwise the NEXT
  // non-Doji candle. The slot's clock time is never shifted.
  const byDate = new Map();
  for (const c of candles) {
    if (!byDate.has(c.date)) byDate.set(c.date, []);
    byDate.get(c.date).push(c);
  }

  const days = new Map();
  for (const [date, rows] of byDate) {
    rows.sort((a,b) => a.time.localeCompare(b.time));
    const resolved = {};

    for (const target of targetTimes) {
      const nextNonDoji = rows.find(c => c.time >= target && c.open !== c.close);
      if (nextNonDoji) {
        resolved[target] = nextNonDoji.close > nextNonDoji.open ? "G" : "R";
      }
    }
    if (Object.keys(resolved).length) days.set(date, resolved);
  }

  const allDates = [...days.keys()].sort();
  return { days, minDate: allDates[0] || null, maxDate: allDates[allDates.length - 1] || null };
}

function formatDate(d) {
  if (!d) return "";
  const [y,m,day] = d.split(".");
  return `${day}/${m}/${y}`;
}

function parseDateKey(d) {
  if (!d) return "";
  const [y,m] = d.split(".");
  return `${y}-${m}`;
}

function aggregateSlot(days, slot, startDate, endDate) {
  let s1=0,s2=0,s3=0,s4=0,loose=0,daysCount=0;
  const looseDates=[];
  const orders=[];
  const lastStep = slot.times.length; // 4

  for (const [date, results] of days) {
    if (startDate && date < startDate) continue;
    if (endDate && date > endDate) continue;

    // A day is valid only when ALL 4 selected slots have been resolved.
    // This prevents a missing candle from being silently skipped and changing
    // the martingale step/loose count.
    if (slot.times.some(time => !results[time])) continue;

    let step = 1;
    let resolved = false;

    for (const time of slot.times) {
      const result = results[time];
      if (result === "R") {
        if (step === 1) s1++;
        else if (step === 2) s2++;
        else if (step === 3) s3++;
        else s4++;
        orders.push({ date, step, result:"WIN" });
        resolved = true;
        break;
      }

      // G = loss for this martingale step; advance to the next selected slot.
      if (step === lastStep) {
        loose++;
        looseDates.push(date);
        orders.push({ date, step:lastStep, result:"LOSS" });
        resolved = true;
        break;
      }
      step++;
    }

    if (resolved) daysCount++;
  }

  orders.sort((a,b)=>b.date.localeCompare(a.date));
  return { days:daysCount, s1, s2, s3, s4, loose, win:s1+s2+s3+s4, looseDates, orders };
}

